import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from tangledTree ----
type TangleDatum = { id: string; parents?: string[] };

/** A subset of the Greek theogony: a DAG whose nodes have two parents, laid out in generations. */
const greekGenealogy: TangleDatum[][] = [
  [{ id: 'Chaos' }],
  [{ id: 'Gaea', parents: ['Chaos'] }, { id: 'Uranus' }],
  [
    { id: 'Oceanus', parents: ['Gaea', 'Uranus'] },
    { id: 'Thethys', parents: ['Gaea', 'Uranus'] },
    { id: 'Pontus' },
    { id: 'Rhea', parents: ['Gaea', 'Uranus'] },
    { id: 'Cronus', parents: ['Gaea', 'Uranus'] },
    { id: 'Coeus', parents: ['Gaea', 'Uranus'] },
    { id: 'Phoebe', parents: ['Gaea', 'Uranus'] }
  ],
  [
    { id: 'Doris', parents: ['Oceanus', 'Thethys'] },
    { id: 'Nereus', parents: ['Pontus', 'Gaea'] },
    { id: 'Demeter', parents: ['Rhea', 'Cronus'] },
    { id: 'Hera', parents: ['Rhea', 'Cronus'] },
    { id: 'Zeus', parents: ['Rhea', 'Cronus'] },
    { id: 'Poseidon', parents: ['Rhea', 'Cronus'] },
    { id: 'Leto', parents: ['Coeus', 'Phoebe'] }
  ],
  [
    { id: 'Thetis', parents: ['Doris', 'Nereus'] },
    { id: 'Persephone', parents: ['Zeus', 'Demeter'] },
    { id: 'Ares', parents: ['Zeus', 'Hera'] },
    { id: 'Hephaestus', parents: ['Zeus', 'Hera'] },
    { id: 'Athena', parents: ['Zeus'] },
    { id: 'Apollo', parents: ['Zeus', 'Leto'] },
    { id: 'Artemis', parents: ['Zeus', 'Leto'] }
  ]
];

/** One array per generation, top to bottom; each node names the parents it descends from. */
export type Data = { id: string; parents?: string[] }[][];

const PADDING = 8;
const NODE_HEIGHT = 18;
const NODE_WIDTH = 86;
const BUNDLE_WIDTH = 12;
const LEVEL_PADDING = 12;
/** Vertical separation between the metro tracks leaving one node for its different families. */
const METRO = 4;
const MIN_FAMILY_HEIGHT = 16;
const CORNER = 14;
const BIG_CORNER = NODE_WIDTH + CORNER;
const FONT_SIZE = 10;

/** `families` holds the ids of the bundles this node parents, top-to-bottom on its metro tracks. */
type Node = {
  id: string;
  level: number;
  parents: Node[];
  families: string[];
  bundle: Bundle | null;
  height: number;
  x: number;
  y: number;
};

/** One family: the children sharing an identical parent set, merged into a single trunk. */
type Bundle = { id: string; level: number; span: number; parents: Node[]; links: Link[]; i: number; x: number; y: number };

type Link = { child: Node; parent: Node; bundle: Bundle };

function tangleLayout(levels: Data) {
  const flat = levels.flat();
  const nodes: Node[] = levels.flatMap((level, i) =>
    level.map((d) => ({ id: d.id, level: i, parents: [], families: [], bundle: null, height: 0, x: 0, y: 0 }))
  );
  const byId = new Map(nodes.map((n) => [n.id, n]));
  nodes.forEach((n, i) => {
    n.parents = (flat[i].parents ?? []).flatMap((p) => {
      const parent = byId.get(p);
      return parent ? [parent] : [];
    });
  });

  const bundlesByLevel: Bundle[][] = levels.map(() => []);
  nodes.forEach((n) => {
    if (n.parents.length === 0) return;
    const id = n.parents
      .map((p) => p.id)
      .sort()
      .join('-X-');
    const siblings = bundlesByLevel[n.level];
    let bundle = siblings.find((b) => b.id === id);
    if (!bundle) {
      const span = n.level - (d3.min(n.parents, (p) => p.level) ?? n.level);
      bundle = { id, level: n.level, span, parents: n.parents.slice(), links: [], i: siblings.length, x: 0, y: 0 };
      siblings.push(bundle);
    }
    n.bundle = bundle;
  });
  const bundles = bundlesByLevel.flat();

  const links: Link[] = [];
  nodes.forEach((n) => {
    const bundle = n.bundle;
    if (!bundle) return;
    n.parents.forEach((parent) => links.push({ child: n, parent, bundle }));
  });
  links.forEach((l) => l.bundle.links.push(l));

  // Widest-spanning family first, so long-haul links take the outermost metro track.
  const spanOf = d3.rollup(
    bundles,
    (v) => d3.max(v, (b) => b.span) ?? 0,
    (b) => b.id
  );
  bundles.forEach((b) =>
    b.parents.forEach((p) => {
      if (!p.families.includes(b.id)) p.families.push(b.id);
    })
  );
  nodes.forEach((n) => {
    n.families.sort((a, b) => (spanOf.get(b) ?? 0) - (spanOf.get(a) ?? 0));
    n.height = (Math.max(1, n.families.length) - 1) * METRO;
  });

  let xOffset = PADDING;
  let yOffset = PADDING;
  levels.forEach((level, i) => {
    xOffset += bundlesByLevel[i].length * BUNDLE_WIDTH;
    yOffset += LEVEL_PADDING;
    level.forEach((d) => {
      const n = byId.get(d.id);
      if (!n) return;
      n.x = i * NODE_WIDTH + xOffset;
      n.y = NODE_HEIGHT + yOffset + n.height / 2;
      yOffset += NODE_HEIGHT + n.height;
    });
  });

  let rows = 0;
  levels.forEach((level, i) => {
    bundlesByLevel[i].forEach((b) => {
      b.x =
        (d3.max(b.parents, (p) => p.x) ?? 0) +
        NODE_WIDTH +
        (bundlesByLevel[i].length - 1 - b.i) * BUNDLE_WIDTH;
      b.y = rows * NODE_HEIGHT;
    });
    rows += level.length;
  });

  const trackY = (node: Node, bundleId: string) =>
    node.y + node.families.indexOf(bundleId) * METRO - (node.families.length * METRO) / 2 + METRO / 2;

  // Squeeze each generation up against the tightest family in it, measured before anything moves.
  const gaps = new Map(links.map((l) => [l, l.child.y - trackY(l.parent, l.bundle.id) - 3 * CORNER]));
  let lift = 0;
  levels.forEach((level, i) => {
    const tightest = d3.min(bundlesByLevel[i], (b) => d3.min(b.links, (l) => gaps.get(l) ?? 0));
    lift += (tightest === undefined ? 0 : tightest - MIN_FAMILY_HEIGHT) || 0;
    level.forEach((d) => {
      const n = byId.get(d.id);
      if (n) n.y -= lift;
    });
  });

  const trunks = bundles.map((b) => ({
    key: `${b.level}-${b.id}`,
    d: b.links
      .map((l) => {
        const yTop = trackY(l.parent, b.id);
        // A link skipping a generation rounds off wide, so it reads as one sweep rather than a step.
        const c1 =
          l.child.level - l.parent.level > 1
            ? Math.min(BIG_CORNER, b.x - l.parent.x, b.y - yTop) - CORNER
            : CORNER;
        return `M${l.parent.x} ${yTop}L${b.x - c1} ${yTop}A${c1} ${c1} 90 0 1 ${b.x} ${yTop + c1}L${b.x} ${l.child.y - CORNER}A${CORNER} ${CORNER} 90 0 0 ${b.x + CORNER} ${l.child.y}L${l.child.x} ${l.child.y}`;
      })
      .join('')
  }));

  return {
    nodes,
    trunks,
    width: (d3.max(nodes, (n) => n.x) ?? 0) + NODE_WIDTH + 2 * PADDING,
    height: (d3.max(nodes, (n) => n.y) ?? 0) + NODE_HEIGHT / 2 + 2 * PADDING
  };
}

export default function TangledTree({ data = greekGenealogy, width }:
  { data?: Data; width: number }) {
  const layout = useMemo(() => tangleLayout(data), [data]);

  const height = Math.round((width * layout.height) / layout.width);

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${layout.width} ${layout.height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Tangled tree of a subset of the Greek theogony, where each generation's links bundle into one trunk per pair of parents"
    >
      <g fill="none">
        {layout.trunks.map((t, i) => (
          <g key={t.key}>
            <path d={t.d} stroke="var(--bg)" strokeWidth={5} />
            <path d={t.d} stroke={d3.schemeObservable10[i % 10]} strokeWidth={2} />
          </g>
        ))}
      </g>

      <g strokeLinecap="round" fontSize={FONT_SIZE} paintOrder="stroke">
        {layout.nodes.map((n) => {
          const tick = `M${n.x} ${n.y - n.height / 2}L${n.x} ${n.y + n.height / 2}`;
          return (
            <g key={n.id}>
              <path d={tick} stroke="var(--bg)" strokeWidth={7} />
              <path d={tick} stroke="var(--text)" strokeWidth={3} />
              <text
                x={n.x + 4}
                y={n.y - n.height / 2 - 4}
                fill="var(--text)"
                stroke="var(--bg)"
                strokeWidth={3}
              >
                {n.id}
              </text>
            </g>
          );
        })}
      </g>
    </svg>
  );
}
